mapper.sql:
WHERE 1 = 1
AND ( LOWER(COALESCE(U.UNIV_NAME, A.UNIV_NAME)) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(H.MERCHANT_UID) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(H.PORTONE_PAYMENT_ID) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(H.PORTONE_SCHEDULE_ID) LIKE '%' || LOWER(#{keyword}) || '%' )
AND H.STATUS = #{status}
AND S.PLAN_ID = #{planId}
AND CASE WHEN LOWER(B.PG_PROVIDER) = 'kakaopay' THEN 'KAKAO_PAY' ELSE 'CARD' END = #{method}

mapper.update:
UPDATE SUBSCRIPTION_PAYMENT_HISTORIES
SET STATUS = 'FAILED',
    FAIL_REASON = #{failReason}
WHERE HISTORY_ID = #{historyId}
  AND STATUS = 'READY'

UPDATE SUBSCRIPTION_PAYMENT_HISTORIES
SET PORTONE_SCHEDULE_ID = #{portoneScheduleId}
WHERE HISTORY_ID = #{historyId}
  AND STATUS = 'READY'
